fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    assert!(len > 0, "rotate_right requires a non-empty list");
    // Compute how many positions we actually rotate by (mod length)
    let k = n % len;
    // s is the split point: elements at [s..] go to the front
    let s = len - k;

    // Pre‐allocate a new Vec of the same length
    let mut new_list = Vec::with_capacity(len);
    // Push the suffix [s..len]
    new_list.extend_from_slice(&list[s..]);
    // Then push the prefix [0..s]
    new_list.extend_from_slice(&list[..s]);
    new_list
}

